export enum SupportedDatastores {
    s3 = 's3',
}
/**
 *
 * This Class represents the access information and control data structure for Datastore based Measurement solutions
 * Specifically this is the access information needed for connectors inside of Confluent Cloud to pull data from a clients env.
 * There are many different connectors with different access and control needs.
 * For example a MySQL connector is not the same as a Kinesis Connector
 * */
export class DatastoreAccessInformation {
    /**
     * Underlying resource type which paigo connects to. Default is s3.
     *
     */
    @Matches(
        `^${Object.values(SupportedDatastores)
            .filter((v) => typeof v !== 'number')
            .join('|')}$`,
        'i'
    )
    @IsOptional()
    @ApiProperty({
        enum: SupportedDatastores,
        isArray: false,
        required: false,
        examples: ['s3'],
    })
    public datastoreType?: SupportedDatastores;

    /**
     *
     * Whether paigo is hosting the ingestion endpoint, or it is hosted by the client. Optional, default is `true`.
     * @example 'true'
     */
    @IsString()
    @IsOptional()
    public paigoHosted?: 'true';

    /**
     *
     * What is the cloud environment associated with the ingestion endpoint. Optional, default is `aws`.
     * @example "aws"
     */
    @IsEnum(supportedCloudPlatforms)
    @IsOptional()
    public hostedCloud?: supportedCloudPlatforms;

    /**
     * The Unqiue ID for the cloud env where the resource is hosted. Required.
     * @example "623673123435"
     */
    @IsString()
    @IsNotEmpty()
    public cloudId: string;

    /**
     * The AWS region where the ingestion and DLQ buckets are located. Optional, defaults to us-east-1.
     * @example "us-east-1"
     */
    @IsString()
    @IsOptional()
    public region?: string;

    /**
     * The IAM role ARN created for this measurement to access S3 buckets.
     * Generated during setupAccess.
     * @example "arn:aws:iam::123456789012:role/datastore-mybusiness-abc123"
     */
    @IsString()
    @IsOptional()
    @ApiHideProperty()
    public iamRoleArn?: string;

    /**
     * The external ID used for the IAM role trust policy.
     * Generated during setupAccess.
     * @example "a1b2c3d4-e5f6-7890-abcd-ef1234567890"
     */
    @IsString()
    @IsOptional()
    @ApiHideProperty()
    public externalId?: string;

    /**
     * The S3 ingestion bucket prefix path.
     * Generated during setupAccess.
     * @example "s3://paigo-usage-record-dump-bucket/mybusiness/"
     */
    @IsString()
    @IsOptional()
    @ApiHideProperty()
    public ingestion?: string;

    /**
     * The S3 DLQ bucket prefix path.
     * Generated during setupAccess.
     * @example "s3://paigo-usage-record-dlq-bucket/mybusiness/"
     */
    @IsString()
    @IsOptional()
    @ApiHideProperty()
    public dlq?: string;

    @ApiHideProperty()
    @IsOptional()
    public businessID: string;

    constructor(datastoreAccessInformation: DatastoreAccessInformation) {
        if (datastoreAccessInformation) {
            const {
                cloudId,
                hostedCloud,
                paigoHosted,
                datastoreType,
                businessID,
                region,
                iamRoleArn,
                externalId,
                ingestion,
                dlq,
            } = datastoreAccessInformation;
            this.cloudId = cloudId;
            this.hostedCloud = hostedCloud ? hostedCloud : supportedCloudPlatforms.aws;
            this.paigoHosted = paigoHosted ? paigoHosted : 'true';
            this.datastoreType = datastoreType ? datastoreType : SupportedDatastores.s3;
            this.businessID = businessID;
            this.region = region ? region : 'us-east-1';
            this.iamRoleArn = iamRoleArn;
            this.externalId = externalId;
            this.ingestion = ingestion;
            this.dlq = dlq;
        }
    }

    public static transformer(datastoreAccessInformation: DatastoreAccessInformation, influxPoint: Point) {
        if (datastoreAccessInformation) {
            const { datastoreType: supportedDbs, paigoHosted, hostedCloud, cloudId, region, iamRoleArn, externalId, ingestion, dlq } = datastoreAccessInformation;
            if (supportedDbs) influxPoint.tag('supportedDbs', supportedDbs);
            if (paigoHosted) influxPoint.tag('paigoHosted', paigoHosted);
            if (hostedCloud) influxPoint.tag('hostedCloud', hostedCloud);
            if (cloudId) influxPoint.tag('cloudId', cloudId);
            if (region) influxPoint.tag('region', region);
            if (iamRoleArn) influxPoint.tag('iamRoleArn', iamRoleArn);
            if (externalId) influxPoint.tag('externalId', externalId);
            if (ingestion) influxPoint.tag('ingestion', ingestion);
            if (dlq) influxPoint.tag('dlq', dlq);
        }
        return influxPoint;
    }

    public static dbModelToEntity({
        datastoreType,
        paigoHosted,
        hostedCloud,
        cloudId,
        businessID,
        region,
        iamRoleArn,
        externalId,
        ingestion,
        dlq,
    }: {
        [x: string]: any;
    }) {
        return new DatastoreAccessInformation({
            datastoreType,
            paigoHosted,
            hostedCloud,
            cloudId,
            businessID,
            region,
            iamRoleArn,
            externalId,
            ingestion,
            dlq,
        });
    }

    public static async setupAccess(dbAccessInformation: DatastoreAccessInformation) {
        const { paigoHosted, cloudId, datastoreType, businessID, region, measurementId } = dbAccessInformation;

        if (paigoHosted && datastoreType === SupportedDatastores.s3) {
            const iamClient = new IAMClient({ region: region || 'us-east-1' });
            const roleName = `datastore-${businessID}-${measurementId}`;
            const externalId = randomUUID();
            const trustPolicy = {
                Version: '2012-10-17',
                Statement: [
                    {
                        Effect: 'Allow',
                        Principal: {
                            AWS: `arn:aws:iam::${cloudId}:root`,
                        },
                        Action: 'sts:AssumeRole',
                        Condition: {
                            StringEquals: {
                                'sts:ExternalId': externalId,
                            },
                        },
                    },
                ],
            };

            try {
                await iamClient.send(
                    new CreateRoleCommand({
                        RoleName: roleName,
                        AssumeRolePolicyDocument: JSON.stringify(trustPolicy),
                        Description: `Paigo S3 ingestion role for business ${businessID} measurement ${measurementId}`,
                        MaxSessionDuration: 3600,
                    })
                );
            } catch (e) {
                if (e.name === 'EntityAlreadyExistsException') {
                    const existingRole = await iamClient.send(new GetRoleCommand({ RoleName: roleName }));
                    if (existingRole.Role) {
                        dbAccessInformation.iamRoleArn = existingRole.Role.Arn;
                        const policyDoc = JSON.parse(decodeURIComponent(existingRole.Role.AssumeRolePolicyDocument));
                        const statement = policyDoc.Statement[0];
                        if (statement.Condition?.StringEquals?.['sts:ExternalId']) {
                            dbAccessInformation.externalId = statement.Condition.StringEquals['sts:ExternalId'];
                        }
                    }
                } else {
                    throw e;
                }
            }

            if (!dbAccessInformation.iamRoleArn) {
                const roleResponse = await iamClient.send(new GetRoleCommand({ RoleName: roleName }));
                dbAccessInformation.iamRoleArn = roleResponse.Role.Arn;
            }

            if (!dbAccessInformation.externalId) {
                dbAccessInformation.externalId = externalId;
            }

            const bucketName = process.env.DB_MEASUREMENT_BUCKET_NAME;
            const dlqBucketName = process.env.DB_MEASUREMENT_DLQ_BUCKET_NAME;
            const ingestionPrefix = `${businessID}/`;
            const dlqPrefix = `${businessID}/`;

            const rolePolicy = {
                Version: '2012-10-17',
                Statement: [
                    {
                        Sid: 'S3IngestionAccess',
                        Effect: 'Allow',
                        Action: ['s3:PutObject', 's3:GetObject', 's3:ListBucket'],
                        Resource: [
                            `arn:aws:s3:::${bucketName}`,
                            `arn:aws:s3:::${bucketName}/${ingestionPrefix}*`,
                        ],
                    },
                    {
                        Sid: 'S3DLQAccess',
                        Effect: 'Allow',
                        Action: ['s3:PutObject', 's3:GetObject', 's3:ListBucket'],
                        Resource: [
                            `arn:aws:s3:::${dlqBucketName}`,
                            `arn:aws:s3:::${dlqBucketName}/${dlqPrefix}*`,
                        ],
                    },
                ],
            };

            await iamClient.send(
                new PutRolePolicyCommand({
                    RoleName: roleName,
                    PolicyName: 'PaigoS3Access',
                    PolicyDocument: JSON.stringify(rolePolicy),
                })
            );

            dbAccessInformation.ingestion = `s3://${bucketName}/${ingestionPrefix}`;
            dbAccessInformation.dlq = `s3://${dlqBucketName}/${dlqPrefix}`;
            dbAccessInformation.region = region || 'us-east-1';
        }
    }

    public static async updateAccess(dbAccessInformation: DatastoreAccessInformation) {
        const { cloudId, businessID, measurementId, region, iamRoleArn, externalId } = dbAccessInformation;

        if (!iamRoleArn || !externalId) {
            throw new BadRequestException('IAM role ARN and external ID are required for updateAccess');
        }

        const iamClient = new IAMClient({ region: region || 'us-east-1' });
        const roleName = `datastore-${businessID}-${measurementId}`;

        const trustPolicy = {
            Version: '2012-10-17',
            Statement: [
                {
                    Effect: 'Allow',
                    Principal: {
                        AWS: `arn:aws:iam::${cloudId}:root`,
                    },
                    Action: 'sts:AssumeRole',
                    Condition: {
                        StringEquals: {
                            'sts:ExternalId': externalId,
                        },
                    },
                },
            ],
        };

        await iamClient.send(
            new UpdateAssumeRolePolicyCommand({
                RoleName: roleName,
                PolicyDocument: JSON.stringify(trustPolicy),
            })
        );
    }
}

